export enum KeySize {
  BITS_2048 = 2048,
  BITS_4096 = 4096,
}

export interface RSAKeyPair {
  id: string;
  name: string;
  size: KeySize;
  publicKey: string; // PEM format
  privateKey: string; // PEM format
  createdAt: number;
}

export enum CryptoOperation {
  ENCRYPT = 'ENCRYPT',
  DECRYPT = 'DECRYPT',
}

export interface StoredKeyMetadata {
  id: string;
  name: string;
  size: KeySize;
  createdAt: number;
}

import { KeySize } from '../types';

// Helper to convert ArrayBuffer to Base64
const arrayBufferToBase64 = (buffer: ArrayBuffer): string => {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
};

// Helper to convert Base64 to ArrayBuffer
const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

// Convert exported key to PEM format
const exportKeyToPEM = (keyData: ArrayBuffer, type: 'PUBLIC' | 'PRIVATE'): string => {
  const base64 = arrayBufferToBase64(keyData);
  const typeStr = type === 'PUBLIC' ? 'PUBLIC KEY' : 'PRIVATE KEY';

  let pem = `-----BEGIN ${typeStr}-----\n`;
  let offset = 0;
  while (offset < base64.length) {
    pem += base64.substring(offset, offset + 64) + '\n';
    offset += 64;
  }
  pem += `-----END ${typeStr}-----\n`;
  return pem;
};

// Remove PEM header/footer and newlines
const cleanPEM = (pem: string, type: 'PUBLIC' | 'PRIVATE'): string => {
  const typeStr = type === 'PUBLIC' ? 'PUBLIC KEY' : 'PRIVATE KEY';
  const header = `-----BEGIN ${typeStr}-----`;
  const footer = `-----END ${typeStr}-----`;

  let clean = pem.replace(header, '').replace(footer, '');
  clean = clean.replace(/\s/g, ''); // remove all whitespace
  return clean;
};

export const generateRSAKeyPair = async (size: KeySize): Promise<{ publicKey: string; privateKey: string }> => {
  const keyPair = await window.crypto.subtle.generateKey(
    {
      name: "RSA-OAEP",
      modulusLength: size,
      publicExponent: new Uint8Array([1, 0, 1]),
      hash: "SHA-256",
    },
    true,
    ["encrypt", "decrypt"]
  );

  const exportedPublic = await window.crypto.subtle.exportKey("spki", keyPair.publicKey);
  const exportedPrivate = await window.crypto.subtle.exportKey("pkcs8", keyPair.privateKey);

  return {
    publicKey: exportKeyToPEM(exportedPublic, 'PUBLIC'),
    privateKey: exportKeyToPEM(exportedPrivate, 'PRIVATE'),
  };
};

export const encryptData = async (pemPublicKey: string, data: ArrayBuffer): Promise<ArrayBuffer> => {
  const cleanKey = cleanPEM(pemPublicKey, 'PUBLIC');
  const binaryKey = base64ToArrayBuffer(cleanKey);

  const importedKey = await window.crypto.subtle.importKey(
    "spki",
    binaryKey,
    {
      name: "RSA-OAEP",
      hash: "SHA-256"
    },
    false,
    ["encrypt"]
  );

  return await window.crypto.subtle.encrypt(
    {
      name: "RSA-OAEP"
    },
    importedKey,
    data
  );
};

export const decryptData = async (pemPrivateKey: string, data: ArrayBuffer): Promise<ArrayBuffer> => {
  const cleanKey = cleanPEM(pemPrivateKey, 'PRIVATE');
  const binaryKey = base64ToArrayBuffer(cleanKey);

  const importedKey = await window.crypto.subtle.importKey(
    "pkcs8",
    binaryKey,
    {
      name: "RSA-OAEP",
      hash: "SHA-256"
    },
    false,
    ["decrypt"]
  );

  return await window.crypto.subtle.decrypt(
    {
      name: "RSA-OAEP"
    },
    importedKey,
    data
  );
};

import { RSAKeyPair, StoredKeyMetadata } from '../types';

const STORAGE_KEY = 'rsa_manager_keys';

/**
 * In a real Electron app, this service would use `fs` (Node.js) to read/write
 * directories and files. For this Web App version, we simulate the directory
 * structure using LocalStorage.
 */

export const saveKeyToStorage = (keyPair: RSAKeyPair): void => {
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];

  // Check if name exists
  if (existing.some(k => k.name === keyPair.name)) {
    throw new Error(`Key with name "${keyPair.name}" already exists.`);
  }

  const updated = [...existing, keyPair];
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

export const getKeysMetadata = (): StoredKeyMetadata[] => {
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];

  return existing.map(k => ({
    id: k.id,
    name: k.name,
    size: k.size,
    createdAt: k.createdAt
  })).sort((a, b) => b.createdAt - a.createdAt);
};

export const getKeyByName = (name: string): RSAKeyPair | undefined => {
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];
  return existing.find(k => k.name === name);
};

export const deleteKey = (name: string): void => {
  const existingStr = localStorage.getItem(STORAGE_KEY);
  const existing: RSAKeyPair[] = existingStr ? JSON.parse(existingStr) : [];
  const updated = existing.filter(k => k.name !== name);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
};

// Helper to simulate "Downloading" the files to the user's computer
// since we can't write directly to C:/ or /home/ without File System Access API
export const downloadKeyFiles = (keyPair: RSAKeyPair) => {
  const downloadFile = (filename: string, content: string) => {
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Simulate folder download by downloading two files prefixed with folder name
  downloadFile(`${keyPair.name}/public.pem`, keyPair.publicKey);
  downloadFile(`${keyPair.name}/private.pem`, keyPair.privateKey);
};

